INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, 13020011, "", "", "", 13020014, "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, 111031, "いかんいかん\n資材の山に埋もれて\nしまうところだった", "", "", 13020015, "", 302, 10, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, 0, "", "", "", 13020016, "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (1, 3, 2, "nyx_302_yuni_02", "", "", 13020017, "NoItem", 302, 0, 0.2);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (1, 3, 111031, "nyx_302_yuni_02", "", 0.2, 13020018, "nyx_idle_normal", 302, 0, 0.2);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, 111031, "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", "", "", 13020019, "", 302, 10, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 93, 5, "", "", "", 13020020, "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 4, 111031, 0, "", "", 13020021, "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 3, 111031, "nyx_cmn_03", "", "", 13020022, "", 302, 1, 0.2);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, 111031, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", "", "", 13020023, "", 302, 10, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, 0, "", "", "", 13020024, "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 3, 111031, "nyx_301_yuni_01", "", "", 13020025, "", 302, 1, 0.2);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, 111031, "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", "", "", 13020026, "", 302, 10, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, 0, 1, "", "", 13020027, "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, 111031, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", "", "", 13020028, "", 302, 10, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, 0, 1, "", "", 13020029, "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (1, 3, 111031, "nyx_302_yuni_03", "", "", 13020030, "nyx_302_yuni_04", 302, 0, 0.2);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, 111031, "是非もなし\nいざ往かん！", "", "", 13020031, "", 302, 10, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, 0, 1, "", "", 13020032, "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 93, 1.5, "", "", "", 13020033, "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, 111031, "む。奥に入りすぎた\nこれは…出られぬ！\n誰かー！　誰か―！", "", "", 13020034, "", 302, 10, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, 0, "", "", "", 13020035, "", 302, "", "");
